package p1;

public class P1_main {

	public static void main(String[] args) {

		for (int y=1;y<=11;y=y+1) {
			
			System.out.println(y);
		}
		
		// TODO Auto-generated method stub
		
		int x=0;
		while ( x <= 10 ) {
		x = x + 1;
		System.out.println(x);
		}
		
		
		int z=0;
		
		do {
			
			z=z+1;
			System.out.println(z);
		}
		
		while (z<=10);

		
	}

}
